-- 1) criar os grupos novos, ja no tamanho correto (ajuste caminho e tamanho):
ALTER DATABASE ADD LOGFILE GROUP 11 SIZE 1024M;
ALTER DATABASE ADD LOGFILE GROUP 12 SIZE 1024M;
ALTER DATABASE ADD LOGFILE GROUP 13 SIZE 1024M;

-- 2) forcar o ciclo ate o grupo antigo ficar INACTIVE:
ALTER SYSTEM SWITCH LOGFILE;
ALTER SYSTEM CHECKPOINT;

-- 3) conferir o status ANTES de remover:
-- SELECT group#, status, archived FROM v$log ORDER BY group#;

-- 4) remover os antigos, um a um, so quando INACTIVE e archived=YES:
ALTER DATABASE DROP LOGFILE GROUP 1;

ALTER SYSTEM CHECKPOINT;
ALTER SYSTEM SWITCH LOGFILE;
ALTER SYSTEM ARCHIVE LOG CURRENT;
